    df['DecadeLabel'] = df['Decade'].apply(lambda d: f"{d}s")
    df['MoM_Change'] = df['Crude_Oil_Price'].diff()
    df['MoM_Pct'] = df['Crude_Oil_Price'].pct_change() * 100
    df['YoY_Change'] = df['Crude_Oil_Price'].diff(12)
    df['YoY_Pct'] = df['Crude_Oil_Price'].pct_change(12) * 100
    return df


def compute_kpis(df):
    price = df['Crude_Oil_Price']
    min_price = price.min()
    max_price = price.max()
    overall_range = max_price - min_price

    first_price = df.iloc[0]['Crude_Oil_Price']
    last_price = df.iloc[-1]['Crude_Oil_Price']
    first_date = df.iloc[0]['Date']
    last_date = df.iloc[-1]['Date']
    years = (last_date - first_date).days / 365.25
    cagr = ((last_price / first_price) ** (1 / years) - 1) * 100

    mom_abs_idx = df['MoM_Change'].abs().idxmax()
    mom_abs_val = df.loc[mom_abs_idx, 'MoM_Change']
    mom_abs_date = df.loc[mom_abs_idx, 'Date']
    mom_abs_price = df.loc[mom_abs_idx, 'Crude_Oil_Price']

    mom_pct_idx = df['MoM_Pct'].abs().idxmax()
    mom_pct_val = df.loc[mom_pct_idx, 'MoM_Pct']
    mom_pct_date = df.loc[mom_pct_idx, 'Date']

    decade_avg = df.groupby('DecadeLabel')['Crude_Oil_Price'].mean()
    highest_decade = decade_avg.idxmax()
    highest_decade_val = decade_avg.max()

    std_dev = price.std()

    min_idx = price.idxmin()
    max_idx = price.idxmax()
    min_date = df.loc[min_idx, 'Date']
    max_date = df.loc[max_idx, 'Date']

    return {
        'overall_range': overall_range,
        'min_price': min_price,
        'max_price': max_price,
        'min_date': min_date,
        'max_date': max_date,
        'cagr': cagr,
        'first_price': first_price,
        'last_price': last_price,
        'first_date': first_date,
        'last_date': last_date,
        'years': years,
        'mom_abs_val': mom_abs_val,
        'mom_abs_date': mom_abs_date,
        'mom_abs_price': mom_abs_price,
        'mom_pct_val': mom_pct_val,
        'mom_pct_date': mom_pct_date,
        'highest_decade': highest_decade,
        'highest_decade_val': highest_decade_val,
        'std_dev': std_dev,
        'decade_avg': decade_avg,
        'mean_price': price.mean(),
        'median_price': price.median(),
        'total_observations': len(df),
    }


def chart_long_term(df):
    fig, ax = plt.subplots(figsize=(14, 6))
    ax.plot(df['Date'], df['Crude_Oil_Price'], color=PRIMARY, linewidth=1.2, alpha=0.9)
    ax.fill_between(df['Date'], df['Crude_Oil_Price'], alpha=0.15, color=SECONDARY)

    annotations = [
        ('1973-10-01', 'OPEC Oil\nEmbargo', 15, 35),
        ('1979-06-01', 'Iranian\nRevolution', -10, 30),
        ('1986-04-01', 'OPEC Price\nCollapse', 20, 40),
        ('1990-09-01', 'Gulf War\nSpike', 15, 30),
        ('1998-12-01', 'Asian Financial\nCrisis Low', 25, 35),
        ('2008-07-01', 'Pre-GFC\nPeak $133', -40, 30),
        ('2008-12-01', 'GFC\nCrash', 30, 30),
        ('2014-11-01', 'OPEC Price\nWar', 20, 35),
        ('2020-04-01', 'COVID-19\nCrash', 25, 40),
        ('2022-03-01', 'Russia-Ukraine\nWar Spike', -10, 30),
    ]

    for date_str, label, xoff, yoff in annotations:
        date = pd.Timestamp(date_str)
        row = df.loc[(df['Date'] - date).abs().idxmin()]
        ax.annotate(label, xy=(row['Date'], row['Crude_Oil_Price']),
                    xytext=(xoff, yoff), textcoords='offset points',
                    fontsize=7.5, color=ACCENT, fontweight='bold',
                    arrowprops=dict(arrowstyle='->', color=ACCENT, lw=1),
                    ha='center', va='bottom',
                    bbox=dict(boxstyle='round,pad=0.2', facecolor='white', edgecolor=ACCENT, alpha=0.85))

    ax.set_xlabel('Year')
    ax.set_ylabel('Price (USD per Barrel)')
    ax.set_title('Global Crude Oil Prices: Full Historical Trajectory (1970–2026)', fontsize=15, pad=12)
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda x, _: f'${x:,.0f}'))
    ax.set_xlim(df['Date'].min(), df['Date'].max())
    ax.set_ylim(0, df['Crude_Oil_Price'].max() * 1.15)
    fig.tight_layout()
    return fig_to_base64(fig)


def chart_decade_avg(df, kpis):
    decade_stats = df.groupby('DecadeLabel').agg(
        mean=('Crude_Oil_Price', 'mean'),
        std=('Crude_Oil_Price', 'std'),
        min_p=('Crude_Oil_Price', 'min'),
        max_p=('Crude_Oil_Price', 'max'),
    ).reindex(['1970s', '1980s', '1990s', '2000s', '2010s', '2020s'])

    fig, ax = plt.subplots(figsize=(10, 5))
    x = range(len(decade_stats))
    colors_list = [SECONDARY] * len(decade_stats)
    max_idx = decade_stats['mean'].values.argmax()
    colors_list[max_idx] = ACCENT

    bars = ax.bar(x, decade_stats['mean'], color=colors_list, width=0.6, edgecolor='white', linewidth=1.5, zorder=3)
    ax.errorbar(x, decade_stats['mean'], yerr=decade_stats['std'], fmt='none', ecolor='#333', capsize=5, capthick=1.5, zorder=4)

    for i, (bar, val) in enumerate(zip(bars, decade_stats['mean'])):
        ax.text(bar.get_x() + bar.get_width() / 2, bar.get_height() + decade_stats['std'].iloc[i] + 1.5,
                f'${val:.1f}', ha='center', va='bottom', fontweight='bold', fontsize=10, color=DARK_TEXT)

    ax.set_xticks(x)
    ax.set_xticklabels(decade_stats.index, fontsize=11)
    ax.set_ylabel('Average Price (USD/bbl)')
    ax.set_title('Average Crude Oil Price by Decade (with Std Dev)', fontsize=13, pad=10)
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'${v:,.0f}'))
    ax.set_ylim(0, decade_stats['mean'].max() + decade_stats['std'].max() + 15)
    fig.tight_layout()
    return fig_to_base64(fig), decade_stats


def chart_decade_boxplot(df):
    fig, ax = plt.subplots(figsize=(10, 5))
    decades = ['1970s', '1980s', '1990s', '2000s', '2010s', '2020s']
    data_groups = [df[df['DecadeLabel'] == d]['Crude_Oil_Price'].values for d in decades]

    bp = ax.boxplot(data_groups, labels=decades, patch_artist=True, widths=0.5,
                    medianprops=dict(color=ACCENT, linewidth=2),
                    whiskerprops=dict(color=PRIMARY),
                    capprops=dict(color=PRIMARY),
                    flierprops=dict(marker='o', markerfacecolor=ACCENT, markersize=4, alpha=0.5))
    colors_bp = ['#aed6f1', '#f5b7b1', '#abebc6', '#fadbd8', '#d5dbdb', '#f9e79f']
    for patch, c in zip(bp['boxes'], colors_bp):
        patch.set_facecolor(c)
        patch.set_edgecolor(PRIMARY)

    ax.set_ylabel('Price (USD/bbl)')
    ax.set_title('Price Distribution by Decade (Box Plot)', fontsize=13, pad=10)
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'${v:,.0f}'))
    fig.tight_layout()
    return fig_to_base64(fig)


def chart_volatility(df):
    fig, (ax1, ax2) = plt.subplots(2, 1, figsize=(14, 8), sharex=True)

    ax1.bar(df['Date'], df['MoM_Change'], color=[ACCENT if v < 0 else SECONDARY for v in df['MoM_Change']], width=25, alpha=0.8)
    ax1.axhline(0, color='black', linewidth=0.5)
    ax1.set_ylabel('USD Change')
    ax1.set_title('Month-over-Month Absolute Price Change', fontsize=13, pad=8)
    ax1.yaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'${v:+,.0f}'))

    ax2.bar(df['Date'], df['MoM_Pct'], color=[ACCENT if v < 0 else SECONDARY for v in df['MoM_Pct'].fillna(0)], width=25, alpha=0.8)
    ax2.axhline(0, color='black', linewidth=0.5)
    ax2.set_ylabel('% Change')
    ax2.set_xlabel('Year')
    ax2.set_title('Month-over-Month Percentage Price Change', fontsize=13, pad=8)
    ax2.yaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'{v:+.0f}%'))

    fig.tight_layout()
    return fig_to_base64(fig)


def chart_rolling_vol(df):
    fig, ax = plt.subplots(figsize=(14, 5))
    rolling_std_12 = df.set_index('Date')['Crude_Oil_Price'].rolling(12).std()
    rolling_std_36 = df.set_index('Date')['Crude_Oil_Price'].rolling(36).std()

    ax.plot(rolling_std_12.index, rolling_std_12, color=SECONDARY, linewidth=1.2, label='12-Month Rolling Std Dev', alpha=0.8)
    ax.plot(rolling_std_36.index, rolling_std_36, color=ACCENT, linewidth=1.5, label='36-Month Rolling Std Dev')
    ax.fill_between(rolling_std_12.index, rolling_std_12, alpha=0.1, color=SECONDARY)

    ax.set_ylabel('Standard Deviation (USD/bbl)')
    ax.set_title('Rolling Volatility of Crude Oil Prices', fontsize=13, pad=10)
    ax.legend(frameon=True, facecolor='white')
    ax.set_xlim(df['Date'].min(), df['Date'].max())
    fig.tight_layout()
    return fig_to_base64(fig)


def chart_histogram(df):
    fig, ax = plt.subplots(figsize=(10, 5))
    prices = df['Crude_Oil_Price']
    n, bins, patches = ax.hist(prices, bins=40, color=SECONDARY, edgecolor='white', linewidth=0.8, alpha=0.85, zorder=3)

    mean_p = prices.mean()
    median_p = prices.median()
    ax.axvline(mean_p, color=ACCENT, linestyle='--', linewidth=2, label=f'Mean: ${mean_p:.2f}')
    ax.axvline(median_p, color=GOLD, linestyle='-.', linewidth=2, label=f'Median: ${median_p:.2f}')

    ax.set_xlabel('Price (USD/bbl)')
    ax.set_ylabel('Frequency (Months)')
    ax.set_title('Distribution of Monthly Crude Oil Prices (1970–2026)', fontsize=13, pad=10)
    ax.legend(frameon=True, facecolor='white', fontsize=10)
    ax.xaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'${v:,.0f}'))
    fig.tight_layout()
    return fig_to_base64(fig)


def chart_annual_avg(df):
    annual = df.groupby('Year')['Crude_Oil_Price'].mean()
    fig, ax = plt.subplots(figsize=(14, 5))
    ax.bar(annual.index, annual.values, color=SECONDARY, width=0.8, edgecolor='white', linewidth=0.5, zorder=3, alpha=0.85)

    ax.set_xlabel('Year')
    ax.set_ylabel('Average Price (USD/bbl)')
    ax.set_title('Annual Average Crude Oil Price (1970–2026)', fontsize=13, pad=10)
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'${v:,.0f}'))
    ax.set_xlim(1969.5, 2026.5)
    fig.tight_layout()
    return fig_to_base64(fig)


def chart_yoy(df):
    yoy_annual = df.groupby('Year')['Crude_Oil_Price'].mean()
    yoy_pct = yoy_annual.pct_change() * 100

    fig, ax = plt.subplots(figsize=(14, 5))
    colors_yoy = [ACCENT if v < 0 else SECONDARY for v in yoy_pct.values]
    ax.bar(yoy_pct.index, yoy_pct.values, color=colors_yoy, width=0.8, edgecolor='white', linewidth=0.5, zorder=3, alpha=0.85)
    ax.axhline(0, color='black', linewidth=0.5)

    ax.set_xlabel('Year')
    ax.set_ylabel('Year-over-Year Change (%)')
    ax.set_title('Annual Crude Oil Price Change (%)', fontsize=13, pad=10)
    ax.yaxis.set_major_formatter(mticker.FuncFormatter(lambda v, _: f'{v:+.0f}%'))
    ax.set_xlim(1969.5, 2026.5)
    fig.tight_layout()
    return fig_to_base64(fig)


def get_top_shocks(df, n=10):
    valid = df.dropna(subset=['MoM_Change', 'MoM_Pct']).copy()
    valid['AbsMoM'] = valid['MoM_Change'].abs()
    top = valid.nlargest(n, 'AbsMoM')
    return top[['Date', 'Crude_Oil_Price', 'MoM_Change', 'MoM_Pct']].copy()


def get_descriptive_stats(df):
    price = df['Crude_Oil_Price']
    return {
        'count': len(price),
        'mean': price.mean(),
        'median': price.median(),
        'std': price.std(),
        'min': price.min(),
        'max': price.max(),
        'q25': price.quantile(0.25),
        'q75': price.quantile(0.75),
        'q10': price.quantile(0.10),
        'q90': price.quantile(0.90),
        'skew': price.skew(),
        'kurtosis': price.kurtosis(),
        'iqr': price.quantile(0.75) - price.quantile(0.25),
    }


