                <td>${r['min_p']:.2f}</td>
                <td>${r['max_p']:.2f}</td>
                <td>${r['max_p'] - r['min_p']:.2f}</td>
            </tr>"""

    annual_avgs = df.groupby('Year')['Crude_Oil_Price'].mean()
    yoy_pct_annual = annual_avgs.pct_change() * 100
    biggest_annual_gain_yr = yoy_pct_annual.idxmax()
    biggest_annual_gain_val = yoy_pct_annual.max()
    biggest_annual_loss_yr = yoy_pct_annual.idxmin()
    biggest_annual_loss_val = yoy_pct_annual.min()

    html = f"""<!DOCTYPE html>
<html lang="en">
