        <div class="meta">Covering {kpis['total_observations']} monthly observations &bull; {kpis['first_date'].strftime('%B %Y')} to {kpis['last_date'].strftime('%B %Y')} &bull; Generated {datetime.now().strftime('%B %d, %Y')}</div>
